// Plasma Mistletoe desktop layout (generated by scripts/gen-lookandfeel.py).
//
// One matte strip along the bottom: launcher | dial | arc (centred on screen) |
// system tray | status. Windows stop above it. The dashboard sits on the
// desktop, over the dark left of the Mistletoe wallpaper.

const STRIP = 44;

// ---- Dashboard ----------------------------------------------------------
// Separate cards, each its own widget with its own facet shape. The left
// column sits over the dark left of the wallpaper; the power card (live
// graph, hungriest apps, tips) sits top right, over the dark planet.
function addDashboard(desktop, geo) {
    // Plasma snaps desktop widgets to a 16px grid, so every size and gap
    // here is a multiple of 16 (otherwise the snapping eats the gaps).
    const W = 352, GAP = 32, M = 48;
    const card = (section, x, y, w, h) => {
        const widget = desktop.addWidget("org.mistletoe.dashboard", x, y, w, h);
        widget.currentConfigGroup = ["General"];
        widget.writeConfig("section", section);
    };
    let y = M;
    for (const [section, h] of [["clock", 224], ["favorites", 208], ["mostused", 272], ["power", 64]]) {
        card(section, M, y, W, h);
        y += h + GAP;
    }
    // The power card is the big one: live graph, hungriest apps, tips.
    card("hungry", geo.width - M - 448, M, 448, 576);
    // The media card (YouTube / Music) is optional: add "Mistletoe Dashboard"
    // from the widget list and set its card to "media".
}

// ---- Desktop ------------------------------------------------------------
for (const desktop of desktopsForActivity(currentActivity())) {
    desktop.wallpaperPlugin = "org.kde.image";
    desktop.currentConfigGroup = ["Wallpaper", "org.kde.image", "General"];
    desktop.writeConfig("Image", "file://" + userDataPath("data", "wallpapers/Mistletoe"));
    desktop.writeConfig("FillMode", 2); // scaled and cropped

    if (desktop.screen === 0) {
        addDashboard(desktop, screenGeometry(0));
    }
}

// ---- Strip --------------------------------------------------------------
const strip = new Panel("org.kde.panel");
strip.location = "bottom";
strip.height = STRIP;
strip.hiding = "none";      // always shown; maximized windows stop above it
strip.floating = false;
strip.lengthMode = "fill";

strip.addWidget("org.mistletoe.launcher");
// The dial: the active app's menus and every settings page, from the
// left screen edge.
const dial = strip.addWidget("org.mistletoe.dial");
dial.globalShortcut = "Meta+Space";
strip.addWidget("org.mistletoe.arc");

// The tray keeps Plasma's notifications (popups and history), clipboard,
// volume keys and device prompts alive. Only the bell is always shown;
// everything else appears when it needs attention or under the arrow.
// Network, Bluetooth and media live in the status widget instead.
const tray = strip.addWidget("org.kde.plasma.systemtray");
const trayItems = [
    "org.kde.plasma.notifications", "org.kde.plasma.clipboard", "org.kde.plasma.volume",
    "org.kde.plasma.devicenotifier", "org.kde.plasma.battery", "org.kde.plasma.brightness",
    "org.kde.plasma.keyboardlayout", "org.kde.plasma.keyboardindicator",
    "org.kde.plasma.printmanager", "org.kde.plasma.cameraindicator",
    "org.kde.plasma.manage-inputmethod", "org.kde.kdeconnect", "org.kde.plasma.vault"
];
tray.currentConfigGroup = ["General"];
tray.writeConfig("extraItems", trayItems);
tray.writeConfig("knownItems", trayItems.concat([
    "org.kde.plasma.networkmanagement", "org.kde.plasma.bluetooth",
    "org.kde.plasma.mediacontroller", "org.kde.plasma.weather", "org.kde.kscreen"
]));
tray.writeConfig("shownItems", ["org.kde.plasma.notifications"]);
tray.writeConfig("hiddenItems", trayItems.filter(i => i !== "org.kde.plasma.notifications"));
tray.writeConfig("iconSpacing", 1);

strip.addWidget("org.mistletoe.status");
